def extend_diagonal_runs(grid):
    """Extend every diagonal run of two or more same-colored non-background cells through background cells, from the end with the longer open diagonal."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for dr, dc in ((1, 1), (1, -1)):
        seen=set()
        for i in range(h):
            for j in range(w):
                if (i,j) in seen: continue
                c = grid[i][j]
                if c == bg: continue
                run=[(i,j)]; seen.add((i,j))
                y,x=i+dr,j+dc
                while 0<=y<h and 0<=x<w and grid[y][x]==c:
                    run.append((y,x)); seen.add((y,x)); y+=dr; x+=dc
                if len(run)<2: continue
                def extfrom(ey,ex):
                    n=0; y,x=ey+dr,ex+dc
                    while 0<=y<h and 0<=x<w and grid[y][x]==bg:
                        n+=1; y+=dr; x+=dc
                    return n
                fy,fx=run[-1]; by,bx=run[0]
                fwd=extfrom(fy,fx)
                # backward extension is along (-dr,-dc) from run head
                def extback():
                    n=0; y,x=by-dr,bx-dc
                    while 0<=y<h and 0<=x<w and grid[y][x]==bg:
                        n+=1; y-=dr; x-=dc
                    return n
                bwd=extback()
                if fwd>bwd:
                    y,x=fy+dr,fx+dc
                    for _ in range(fwd): out[y][x]=c; y+=dr; x+=dc
                elif bwd>fwd:
                    y,x=by-dr,bx-dc
                    for _ in range(bwd): out[y][x]=c; y-=dr; x-=dc
                else:
                    for y,x in [(fy+t*dr,fx+t*dc) for t in range(1,fwd+1)]+[(by-t*dr,bx-t*dc) for t in range(1,bwd+1)]:
                        out[y][x]=c
    return out
